// Add exact decimal numbers given as strings of any length and return the
// exact sum as a string.
// Each term is an optional leading '-', then one or more ASCII digits 0-9,
// then optionally a '.' followed by one or more ASCII digits. Leading zeros
// and trailing fractional zeros are allowed ("007.50"). Nothing else is
// accepted: no '+', no spaces, no exponent, no '.' without digits on both
// sides ("1." and ".5" are not terms). Terms may have hundreds of digits,
// far beyond any fixed-width integer or float, and the sum must be exact.
// The result is in canonical form: an integer part with no leading zeros
// ("0" when it is zero), then, only if the fractional part is not zero, a
// '.' and the fractional digits with trailing zeros removed; a '-' prefix
// only when the sum is negative ("-0" is never returned).
// The sum of an empty list is "0". If any term is not of the form above,
// return the string "invalid".
// Examples:
//   decimal_sum(["1.5", "2.25"]) == "3.75"
//   decimal_sum(["99999999999999999999", "0.01", "-1"]) == "99999999999999999998.01"
fn decimal_sum(terms: List[Str]) -> Str {
  // each term: (negative, digits of whole then fraction, fraction length)
  let mut parsed: List[(Bool, List[Int], Int)] = [];
  let mut scale = 0;
  for t in terms {
    let neg = starts_with(t, "-");
    let body = if neg { substr(t, 1, str_len(t)) } else { t };
    let (whole, frac, has_dot) = match split_once(body, ".") {
      Some((w, f)) => (w, f, true),
      None => (body, "", false),
    };
    if !all_digits(whole) || (has_dot && !all_digits(frac)) {
      return "invalid";
    }
    parsed = push(parsed, (neg, map(chars(whole ++ frac), |c| unwrap_or(parse_int(c), 0)), str_len(frac)));
    scale = max(scale, str_len(frac));
  }
  let mut width = 0;
  for p in parsed {
    width = max(width, len(p.1) + scale - p.2);
  }
  // signed column sums, least significant column first
  let mut cols: List[Int] = [];
  for i in range(0, width) {
    let mut c = 0;
    for p in parsed {
      let k = len(p.1) - 1 - (i - (scale - p.2));
      if k >= 0 && k < len(p.1) {
        c = if p.0 { c - p.1[k] } else { c + p.1[k] };
      }
    }
    cols = push(cols, c);
  }
  let (negative, low_first) = match normalize(cols) {
    Some(ds) => (false, ds),
    None => (true, unwrap_or(normalize(map(cols, |c| 0 - c)), [])),
  };
  let mut padded = low_first;
  while len(padded) < scale + 1 {
    padded = push(padded, 0);
  }
  let ds = reverse(padded);
  let split = len(ds) - scale;
  let whole = drop_while(take(ds, split), |d| d == 0);
  let frac = reverse(drop_while(reverse(drop(ds, split)), |d| d == 0));
  let mut out = if is_empty(whole) { "0" } else { join(map(whole, |d| show(d)), "") };
  if !is_empty(frac) {
    out = out ++ "." ++ join(map(frac, |d| show(d)), "");
  }
  if negative && out != "0" { "-" ++ out } else { out }
}

fn all_digits(s: Str) -> Bool {
  s != "" && all(chars(s), |c| is_digit(c))
}

// Carry the columns into digits 0..9; None when the total is negative.
fn normalize(cols: List[Int]) -> Option[List[Int]] {
  let mut out: List[Int] = [];
  let mut carry = 0;
  for c in cols {
    let v = c + carry;
    out = push(out, mod_floor(v, 10));
    carry = div_floor(v, 10);
  }
  if carry < 0 {
    return None;
  }
  while carry > 0 {
    out = push(out, carry % 10);
    carry = carry / 10;
  }
  Some(out)
}
